def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def dominant(line):
        counts = Counter(line)
        color, count = counts.most_common(1)[0]
        return color, count / len(line)

    rows = [r for r in range(h)
            if dominant(grid[r])[0] != bg and dominant(grid[r])[1] >= 0.65]
    cols = [c for c in range(w)
            if dominant([grid[r][c] for r in range(h)])[0] != bg
            and dominant([grid[r][c] for r in range(h)])[1] >= 0.65]

    if len(rows) < 2 or len(cols) < 2:
        return [[bg]]

    line_colors = []
    for r in rows:
        line_colors.extend(grid[r][c] for c in range(w) if c not in cols)
    for c in cols:
        line_colors.extend(grid[r][c] for r in range(h) if r not in rows)
    separator = Counter(line_colors).most_common(1)[0][0] if line_colors else bg

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        row = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2]]
            row.append(corners[0] if corners[0] != separator and
                       all(v == corners[0] for v in corners) else bg)
        out.append(row)

    while out and all(v == bg for v in out[0]):
        out.pop(0)
    while out and all(v == bg for v in out[-1]):
        out.pop()
    if out:
        while out[0] and all(row[0] == bg for row in out):
            for row in out:
                row.pop(0)
        while out[0] and all(row[-1] == bg for row in out):
            for row in out:
                row.pop()

    return out if out else [[bg]]
